changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM information_schema.key_column_usage
         WHERE table_schema    = 'market_data'
           AND table_name      = 'price_bar'
           AND constraint_name = 'price_bar_pkey'
           AND column_name     = 'source_app_id'
    ) THEN
        RETURN;
    END IF;

    ALTER TABLE MARKET_DATA.PRICE_BAR
        DROP CONSTRAINT IF EXISTS price_bar_pkey;

    -- Always succeeds: a wider key cannot collide where a narrower one held.
    ALTER TABLE MARKET_DATA.PRICE_BAR
        ADD CONSTRAINT price_bar_pkey
        PRIMARY KEY (INTERNAL_CUSIP, TM_INTERVAL_ID, SOURCE_APP_ID, BAR_TIMESTAMP);

    DROP INDEX IF EXISTS MARKET_DATA.IX_PRICE_BAR_LATEST;
    CREATE INDEX IX_PRICE_BAR_LATEST
        ON MARKET_DATA.PRICE_BAR (
            INTERNAL_CUSIP, TM_INTERVAL_ID, SOURCE_APP_ID, BAR_TIMESTAMP DESC
        )
        INCLUDE (CLOSE_PX);
END $$;

rollback.sql:
DROP INDEX IF EXISTS MARKET_DATA.IX_PRICE_BAR_LATEST;
ALTER TABLE MARKET_DATA.PRICE_BAR DROP CONSTRAINT IF EXISTS price_bar_pkey;
ALTER TABLE MARKET_DATA.PRICE_BAR
    ADD CONSTRAINT price_bar_pkey
    PRIMARY KEY (INTERNAL_CUSIP, TM_INTERVAL_ID, BAR_TIMESTAMP);
CREATE INDEX IX_PRICE_BAR_LATEST
    ON MARKET_DATA.PRICE_BAR (INTERNAL_CUSIP, TM_INTERVAL_ID, BAR_TIMESTAMP DESC)
    INCLUDE (CLOSE_PX);
